UPDATE app_settings SET strict_rules = strict_rules || ARRAY[
'เมื่อ AI บอกว่า "จะประสานเจ้าหน้าที่/แจ้งเจ้าหน้าที่/ส่งต่อให้ทีมงาน/ให้แอดมินติดต่อกลับ" หรือสัญญาว่าจะมีคนมาตอบ → ต้องหยุดทำงานทันที ห้ามตอบข้อความถัดไปอีก ปล่อยให้แอดมินมารับช่วง (ระบบจะตั้ง ai_active=false อัตโนมัติ)',
'ฟังให้ครบก่อนถาม: ถ้าลูกค้าบอกชัดว่า "ขอแค่ X" หรือ "ขอ X ก่อน" (เช่น ขอราคาขนส่งก่อน, ขอเมนูก่อน) → ตอบเฉพาะสิ่งที่ลูกค้าขอ ห้ามแถมคำถามอื่นต่อท้าย เช่น "สนใจบุฟเฟต์หรือซุ้มดีคะ?" รอให้ลูกค้าได้สิ่งที่ขอก่อน ค่อยถามต่อในรอบถัดไปถ้าจำเป็น'
]::text[]
WHERE key='ai_config';